  ('C3-L1-O05', 6, 1, 0, '["تفقد إلكترونين وتصبح Mg²⁺", "تكتسب ستة إلكترونات وتصبح Mg⁶⁻", "تفقد إلكترونين وتصبح Mg²⁻"]'::jsonb, '["", "اكتساب ستة إلكترونات يتطلب طاقة كبيرة، والفلز يميل إلى الفقد.", "فقد الإلكترونات يعطي شحنة موجبة لا سالبة."]'::jsonb),
  ('C3-L2-O01', 4, 1, 0, '["مركب يتكون من أيونات موجبة وسالبة بينها تجاذب كهروستاتيكي", "مركب يتكون من عنصرين لافلزيين متشاركين في الإلكترونات", "خليط من عنصرين فلزيين أو أكثر"]'::jsonb, '["", "المشاركة بين لافلزين لا تكوّن أيونات.", "هذا وصف السبيكة لا المركب الأيوني."]'::jsonb),
