  ('C3-L2-O03', 1, 1, 0, '["درجات انصهار وغليان مرتفعة", "توصيل الكهرباء في الحالة الصلبة", "القابلية للطرق والسحب"]'::jsonb, '["", "المركب الأيوني الصلب لا يوصل الكهرباء؛ يوصلها مصهورًا أو محلولًا.", "القابلية للطرق والسحب من خواص الفلزات؛ المركبات الأيونية هشة."]'::jsonb),
  ('C3-L2-O03', 3, 2, 1, '["في جميع الحالات بالقدر نفسه", "في الحالة المنصهرة أو في المحلول المائي", "في الحالة الصلبة فقط"]'::jsonb, '["الصلب لا يوصل، بينما يوصل المصهور والمحلول، فالتوصيل يختلف باختلاف الحالة.", "", "الأيونات في الحالة الصلبة مقيدة في الشبكة فلا يوصل الصلب."]'::jsonb),
  ('C3-L2-O03', 4, 1, 0, '["وحدات منتظمة متكررة تُسمى البلورات", "جزيئات منفصلة متباعدة", "سلاسل عشوائية غير منتظمة"]'::jsonb, '["", "المركب الأيوني لا يتكون من جزيئات منفصلة بل من شبكة متصلة من الأيونات.", "ترتيب الأيونات منتظم ومتكرر لا عشوائي."]'::jsonb),
