  ('C3-L2-O03', 7, 1, 0, '["مكعبة، والنسبة 1:1", "مكعبة، والنسبة 1:2", "سداسية، والنسبة 2:1"]'::jsonb, '["", "شحنتا Na⁺ وCl⁻ متساويتان في المقدار فالنسبة 1:1 لا 1:2.", "بلورة NaCl مكعبة لا سداسية، والنسبة 1:1."]'::jsonb),
  ('C3-L2-O04', 1, 2, 1, '["الطاقة اللازمة لفصل أيونين اثنين فقط من البلورة", "الطاقة اللازمة لفصل أيونات مول واحد من المركب الأيوني", "الطاقة اللازمة لنزع إلكترون من ذرة غازية متعادلة"]'::jsonb, '["طاقة الشبكة تخص أيونات مول كامل من المركب لا زوجًا واحدًا من الأيونات.", "", "هذا وصف لطاقة التأين لا لطاقة الشبكة البلورية."]'::jsonb),
  ('C3-L2-O04', 3, 1, 0, '["ترتيب هندسي ثلاثي الأبعاد للجسيمات", "خليط متجانس من فلزين أو أكثر", "مجموعة ذرات تحمل شحنة كهربائية"]'::jsonb, '["", "هذا وصف قريب من السبيكة لا البلورة.", "هذا وصف الأيون عديد الذرات."]'::jsonb),
  ('C3-L2-O04', 4, 2, 1, '["يلزم نحو 790 kJ لفصل أيون Na⁺ واحد عن أيون Cl⁻ واحد", "يلزم نحو 790 kJ لفصل أيونات 1 mol من NaCl", "ينطلق نحو 790 kJ عند صهر 1 g من NaCl"]'::jsonb, '["القيمة تخص مولًا كاملًا من الأيونات لا زوجًا واحدًا.", "", "طاقة الشبكة تخص فصل أيونات مول كامل لا صهر جرام."]'::jsonb),
