  ('C3-L2-O05', 1, 1, 0, '["محلول المركب الأيوني القادر على توصيل الكهرباء", "مركب أيوني صلب يوصل الكهرباء", "محلول مادة لا يوصل الكهرباء"]'::jsonb, '["", "المركب الأيوني الصلب لا يوصل الكهرباء أصلًا.", "الإلكتروليت يوصل الكهرباء بحكم تعريفه."]'::jsonb),
  ('C3-L2-O05', 3, 2, 1, '["لأن الماء النقي موصل جيد للكهرباء", "لأن أيوناته حرة الحركة فتنقل الشحنات", "لأن فيه إلكترونات حرة كالفلزات"]'::jsonb, '["الماء النقي رديء التوصيل؛ التوصيل سببه الأيونات الذائبة.", "", "التوصيل في المحلول الأيوني يتم بحركة الأيونات لا بالإلكترونات الحرة."]'::jsonb),
  ('C3-L2-O05', 4, 1, 0, '["الأيونات الموجبة والسالبة", "الإلكترونات الحرة فقط", "جزيئات الماء المتعادلة"]'::jsonb, '["", "الإلكترونات الحرة تنقل الشحنة في الفلزات لا في المحاليل الأيونية.", "الجزيئات المتعادلة لا تحمل شحنة فلا تنقل التيار."]'::jsonb),
  ('C3-L2-O05', 6, 2, 1, '["المركب يتحول إلى فلز موصل", "الأيونات تنفصل وتتحرك بحرية في المحلول", "الأيونات تتحول إلى ذرات متعادلة"]'::jsonb, '["الذوبان لا يحوّل المركب الأيوني إلى فلز.", "", "الأيونات تبقى مشحونة في المحلول، ولو تحولت إلى ذرات متعادلة لما وصل المحلول."]'::jsonb),
  ('C3-L2-O05', 7, 1, 0, '["إلكتروليت يوصل الكهرباء", "عازل يمنع مرور الكهرباء", "يحتوي على إلكترونات حرة كالفلزات"]'::jsonb, '["", "الماء المالح ليس عازلًا؛ فيه أيونات حرة توصل الكهرباء.", "التوصيل في الماء المالح سببه الأيونات لا الإلكترونات الحرة."]'::jsonb),
  ('C3-L2-O06', 2, 2, 1, '["متساويان؛ لأن الأنيون واحد", "MgCl₂؛ لأن شحنة Mg²⁺ أكبر", "NaCl؛ لأن شحنة Na⁺ أصغر"]'::jsonb, '["الأنيون واحد لكن الكاتيونين مختلفان في الشحنة، فلا تتساوى الطاقتان.", "", "طاقة الشبكة تتناسب طرديًا مع الشحنة، فالشحنة الأصغر تعطي طاقة أقل."]'::jsonb),
  ('C3-L2-O06', 3, 1, 0, '["طاقة شبكة NaI أكبر لأن Na⁺ أصغر حجمًا", "طاقة شبكة KI أكبر لأن K⁺ أكبر حجمًا", "متساويتان لتساوي شحنتي Na⁺ وK⁺"]'::jsonb, '["", "الأيون الأكبر حجمًا يزيد المسافة بين الأيونات فيضعف التجاذب وتقل طاقة الشبكة.", "تساوي الشحنة لا يكفي؛ فحجم الأيون يؤثر أيضًا."]'::jsonb),
  ('C3-L2-O06', 5, 2, 1, '["NaI", "CaCl₂", "NaCl"]'::jsonb, '["NaI شحنة كاتيونه +1 وأنيونه I⁻ أكبر حجمًا، فطاقة شبكته الأقل بين مركبات الصوديوم.", "", "شحنة Na⁺ في NaCl تساوي +1 فقط، وهي أقل من شحنة Ca²⁺."]'::jsonb),
  ('C3-L2-O06', 6, 1, 0, '["تتناسب طرديًا مع شحنة الأيونات وعكسيًا مع حجمها", "تتناسب عكسيًا مع شحنة الأيونات وطرديًا مع حجمها", "تتناسب طرديًا مع شحنة الأيونات ومع حجمها"]'::jsonb, '["", "عكس الصحيح في العاملين كليهما.", "الحجم الأكبر يقلل طاقة الشبكة، فالعلاقة مع الحجم عكسية."]'::jsonb),
  ('C3-L2-O06', 7, 1, 0, '["لأن شحنتي Mg²⁺ وO²⁻ أكبر فتزداد طاقة الشبكة", "لأن الكتلة المولية لـ MgO أكبر من NaCl", "لأن أيونات MgO أكبر حجمًا من أيونات NaCl"]'::jsonb, '["", "الكتلة المولية لـ MgO (نحو 40 g/mol) أصغر من NaCl (58.5 g/mol)، والكتلة ليست العامل المحدد.", "الحجم الأكبر يقلل طاقة الشبكة ولا يرفع درجة الانصهار."]'::jsonb),
