-- =====================================================================
-- تصحيح مفاتيح الإجابة (2026-10-16): 73 سؤال اختيار من متعدد كان الخيار المحدد فيها لا يطابق التفسير
-- (72 في الفصل 3 وسؤال في الفصل 1). السبب: رُتّبت البدائل بعد كتابة المفتاح فتزحزح رقم الإجابة وملاحظات البدائل.
-- راجع كل سؤال مراجعة علمية مستقلة، وطابق التصحيح التفسير وملاحظات البدائل في كل الحالات.
-- آمن للتكرار: لا يغيّر إلا سؤالًا ما زالت بدائله ومفتاحه كما وُلدت؛ وما عدّلته يدويًا يُعرض في النتيجة ولا يُمس.
-- يصحّح أيضًا نتائج تدريب الطلاب السابقة على هذه الأسئلة (صحيح/خطأ ودرجة الجلسة).
-- التنفيذ: انسخ الملف كاملًا في SQL Editor ثم Run.
-- =====================================================================
begin;
create temp table _fix (code text, n int, old_ci int, new_ci int, opts jsonb, notes jsonb) on commit drop;

create temp table _hit on commit drop as
  select q.id, f.* from _fix f
  join public.objectives o on o.code = f.code
  join public.questions q on q.objective_id = o.id and q.type = 'mcq' and q.number = f.n
  join public.question_answers a on a.question_id = q.id
  where q.options = f.opts and a.correct_index = f.old_ci;

update public.question_answers a set correct_index = h.new_ci, distractor_notes = h.notes from _hit h where a.question_id = h.id;
update public.practice_answers p set correct = (p.choice = h.new_ci) from _hit h where p.question_id = h.id;
update public.practice_sessions s set score = (select count(*) filter (where pa.correct) from public.practice_answers pa where pa.session_id = s.id)
  where s.finished_at is not null and s.id in (select pa.session_id from public.practice_answers pa join _hit h on h.id = pa.question_id);
  select 'question', h.id, 'edit', jsonb_build_object('correctIndex', h.old_ci), jsonb_build_object('correctIndex', h.new_ci),
    'تصحيح مفتاح الإجابة: الخيار المحدد لم يطابق التفسير (مراجعة 2026-10-16)', 'مالك المشروع' from _hit h;

-- النتيجة: صُحّح الآن، وكان صحيحًا من قبل، ويحتاج مراجعة يدوية (عُدّلت بدائله أو مفتاحه بعد التوليد)
select
  (select count(*) from _hit) as "صُحّح الآن",
  (select count(*) from _fix f join public.objectives o on o.code = f.code join public.questions q on q.objective_id = o.id and q.type = 'mcq' and q.number = f.n
     join public.question_answers a on a.question_id = q.id where a.correct_index = f.new_ci and q.options = f.opts and not exists (select 1 from _hit h where h.id = q.id)) as "صحيح من قبل",
  (select coalesce(string_agg(f.code || ' سؤال ' || f.n, '، '), 'لا شيء') from _fix f
     where not exists (select 1 from public.objectives o join public.questions q on q.objective_id = o.id and q.type = 'mcq' and q.number = f.n
       join public.question_answers a on a.question_id = q.id where o.code = f.code and q.options = f.opts and a.correct_index in (f.old_ci, f.new_ci))) as "يحتاج مراجعة يدوية";
commit;
